import Foundation
import Testing

@testable import ContextCLI
@testable import ContextCore

/// Keeps the Claude Code mod's golden strings in lockstep with the real CLI output.
///
/// The mod's tests cannot read files or run the CLI, so `golden.ts` carries the output of
/// `personakit contract` and `personakit export` as string constants. This test regenerates the
/// expected file text and fails when the checked-in copy has drifted.
struct CLIModFixtureTests {
  private static let header =
    "// Generated by CLIModFixtureTests. Do not edit; set PK_RECORD_MOD_FIXTURES=1 and run the test to regenerate."

  private var goldenURL: URL {
    fixturesRootURL()
      .deletingLastPathComponent()
      .appendingPathComponent("Integrations/ClaudeCode/hooks/fixtures/golden.ts")
  }

  private func runCLI(_ command: String) -> String {
    captureStdout {
      _ = PersonaKitCLI().run(arguments: [
        "personakit", command,
        "--root", readOnlyFixtureRootURL().path,
        "--no-global", "--no-project",
        "--session", "read-only-auditor_audit-pass",
      ])
    }
  }

  private func runList(root: URL) -> String {
    captureStdout {
      _ = PersonaKitCLI().run(arguments: [
        "personakit", "list", "all", "--json",
        "--root", root.path,
        "--no-global", "--no-project",
      ])
    }
  }

  private var mergedProjectRootURL: URL {
    fixturesRootURL().appendingPathComponent("internal-agent-root/.personakit")
  }

  private var mergedGlobalRootURL: URL {
    fixturesRootURL().appendingPathComponent("kit-root")
  }

  /// `list all --json` over a project root layered on a global root. `--root` pins only the project root, so this
  /// calls the renderer directly. Global rows, shadowed rows, kits, skills, and several sessions come from this pair.
  private func mergedList() -> String {
    let project = mergedProjectRootURL
    let global = mergedGlobalRootURL
    let rendered = ListJSONCommand.render(
      scopes: ScopeSet(projectScopeURL: project, globalScopeURL: global),
      entityType: .all
    )
    precondition(rendered.exitCode == 0, "merged fixture pair must render a success document")
    let projectNormalized = normalize(rendered.output, root: project, placeholder: "<PROJECT>")
    return normalize(projectNormalized, root: global, placeholder: "<GLOBAL>")
  }

  /// A temp root holding the starter library plus one persona file that is not valid JSON.
  private func malformedPersonaRoot() throws -> URL {
    let root = try makeTempDirectory().appendingPathComponent("Project/.personakit")
    try PersonaKitInitializer().run(destination: root.path)
    let broken = root.appendingPathComponent("Packs/personas/broken.persona.json")
    try FileManager.default.createDirectory(
      at: broken.deletingLastPathComponent(),
      withIntermediateDirectories: true
    )
    try Data("{".utf8).write(to: broken)
    return root
  }

  /// Replaces every spelling of `root` (plain, standardized, and JSON-escaped) with `placeholder`.
  private func normalize(_ text: String, root: URL, placeholder: String = "<ROOT>") -> String {
    let spellings = [root.path, root.standardizedFileURL.path, root.resolvingSymlinksInPath().path]
    var result = text
    for spelling in Set(spellings).sorted(by: { $0.count > $1.count }) {
      result = result.replacingOccurrences(of: spelling.replacingOccurrences(of: "/", with: "\\/"), with: placeholder)
      result = result.replacingOccurrences(of: spelling, with: placeholder)
    }
    return result
  }

  private func literal(_ value: String) throws -> String {
    let data = try JSONEncoder().encode(value)
    return String(decoding: data, as: UTF8.self)
  }

  private func sortedJSON<Value: Encodable>(_ value: Value) throws -> String {
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.sortedKeys]
    return String(decoding: try encoder.encode(value), as: UTF8.self)
  }

  private func flattened(_ classes: [(actionClass: String, tools: [String])]) -> [String: String] {
    var map: [String: String] = [:]
    for (actionClass, tools) in classes {
      for tool in tools { map[tool] = actionClass }
    }
    return map
  }

  private func toolActionClassesJSON() throws -> String {
    try sortedJSON(flattened(ClaudeCodeEnforcement.toolActionClasses))
  }

  private func openCodeToolActionClassesJSON() throws -> String {
    try sortedJSON(flattened(OpenCodeEnforcement.toolActionClasses))
  }

  private func claudeReadOnlyToolsJSON() throws -> String {
    try sortedJSON(ClaudeCodeEnforcement.readOnlyTools.sorted())
  }

  private func claudeMCPResourceToolsJSON() throws -> String {
    try sortedJSON(ClaudeCodeEnforcement.mcpResourceTools.sorted())
  }

  private func claudeSubagentToolsJSON() throws -> String {
    try sortedJSON(ClaudeCodeEnforcement.subagentTools.sorted())
  }

  private func claudeLocalSubagentTypesJSON() throws -> String {
    try sortedJSON(ClaudeCodeEnforcement.localSubagentTypes.sorted())
  }

  private func personaKitMCPToolNamesJSON() throws -> String {
    try sortedJSON(ClaudeCodeEnforcement.personaKitMCPToolNames.sorted())
  }

  private func openCodeReadOnlyToolsJSON() throws -> String {
    try sortedJSON(OpenCodeEnforcement.readOnlyTools.sorted())
  }

  private func expectedGoldenText() throws -> String {
    let rootSpelling = readOnlyFixtureRootURL().path.replacingOccurrences(of: "/", with: "\\/")
    let contract = runCLI("contract").replacingOccurrences(of: rootSpelling, with: "<ROOT>")
    let export = runCLI("export")
    let list = normalize(runList(root: readOnlyFixtureRootURL()), root: readOnlyFixtureRootURL())
    let merged = mergedList()
    let errorsRoot = try malformedPersonaRoot()
    let listErrors = normalize(runList(root: errorsRoot), root: errorsRoot)

    return [
      Self.header,
      "export const CONTRACT_JSON = \(try literal(contract))",
      "export const LIST_JSON = \(try literal(list))",
      "export const LIST_ERRORS_JSON = \(try literal(listErrors))",
      "export const LIST_MERGED_JSON = \(try literal(merged))",
      "export const EXPORT_MD = \(try literal(export))",
      "export const TOOL_ACTION_CLASSES_JSON = \(try literal(try toolActionClassesJSON()))",
      "export const CLAUDE_READ_ONLY_TOOLS_JSON = \(try literal(try claudeReadOnlyToolsJSON()))",
      "export const CLAUDE_MCP_RESOURCE_TOOLS_JSON = \(try literal(try claudeMCPResourceToolsJSON()))",
      "export const CLAUDE_SUBAGENT_TOOLS_JSON = \(try literal(try claudeSubagentToolsJSON()))",
      "export const CLAUDE_LOCAL_SUBAGENT_TYPES_JSON = \(try literal(try claudeLocalSubagentTypesJSON()))",
      "export const PERSONAKIT_MCP_TOOL_NAMES_JSON = \(try literal(try personaKitMCPToolNamesJSON()))",
      "export const OPENCODE_TOOL_ACTION_CLASSES_JSON = \(try literal(try openCodeToolActionClassesJSON()))",
      "export const OPENCODE_READ_ONLY_TOOLS_JSON = \(try literal(try openCodeReadOnlyToolsJSON()))",
    ].joined(separator: "\n") + "\n"
  }

  @Test
  func goldenFileMatchesCLIOutput() throws {
    let expected = try expectedGoldenText()

    if ProcessInfo.processInfo.environment["PK_RECORD_MOD_FIXTURES"] == "1" {
      try FileManager.default.createDirectory(
        at: goldenURL.deletingLastPathComponent(),
        withIntermediateDirectories: true
      )
      try expected.write(to: goldenURL, atomically: true, encoding: .utf8)
      Issue.record("Recorded \(goldenURL.path); rerun without PK_RECORD_MOD_FIXTURES.")
      return
    }

    let actual = try String(contentsOf: goldenURL, encoding: .utf8)
    #expect(actual == expected)
  }
}
